attempts.script:
# Get all nets
set all_nets [get_nets *]

# Open output file
set output_file [open outputs/unloaded_nets.txt w]

foreach net $all_nets {
    # Get all pins connected to this net
    set pins [get_pins -of_objects $net]

    # Get all ports connected to this net
    set ports [get_ports -of_objects $net]

    # Check if there is at least one driver (output pin from a cell)
    # We look for pins that are output direction
    set has_driver 0
    set driver_pin ""
    foreach pin $pins {
        if { [sta::pin_direction $pin] == "output" } {
            set has_driver 1
            set driver_pin $pin
            break
        }
    }

    # If no driver, skip
    if { $has_driver == 0 } {
        continue
    }

    # Check for loads
    # Load is defined as: cell input pin OR top-level output port

    set has_load 0

    # Check cell input pins
    foreach pin $pins {
        if { [sta::pin_direction $pin] == "input" } {
            set has_load 1
            break
        }
    }

    # If no cell input pins, check for top-level output ports
    if { $has_load == 0 } {
        foreach port $ports {
            if { [sta::port_direction $port] == "output" } {
                set has_load 1
                break
            }
        }
    }

    # If no loads, it's an unloaded net
    if { $has_load == 0 } {
        puts $output_file "[get_full_name $net] [get_full_name $driver_pin]"
    }
}

close $output_file
